"use client";

// Mode-aware assembly and keyboard dispatch share the same four-way adapter.
/* eslint-disable complexity, no-nested-ternary */

import { Autocomplete as BaseAutocomplete } from "@base-ui/react/autocomplete";
import { Combobox } from "@base-ui/react/combobox";
import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cn } from "cn";
import { CheckIcon, ChevronDownIcon, XIcon } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { createContext, useCallback, useContext, useId, useState } from "react";
import type { ComponentProps, Ref, ReactNode } from "react";

import { AutocompleteRoot, useAutocomplete } from "./autocomplete-root";
import { AutocompleteFeedback } from "./autocomplete-feedback";
import { AutocompletePagination } from "./autocomplete-pagination";
import type {
  AutocompleteContentProps,
  AutocompleteInputProps,
  AutocompleteProps,
} from "./autocomplete-types";
import { groupAutocompleteItems } from "./autocomplete-utils";

const surface =
  "bg-background bg-linear-to-b from-white/10 to-black/10 dark:bg-input/30";
const control =
  "min-h-9 w-full min-w-0 rounded-md border border-input px-3 text-sm text-foreground shadow-xs outline-none transition-[color,box-shadow] focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50 data-disabled:cursor-not-allowed data-disabled:opacity-50 data-invalid:border-destructive data-invalid:ring-[3px] data-invalid:ring-destructive/20 dark:data-invalid:ring-destructive/40 motion-reduce:transition-none";
const action =
  "inline-flex size-7 shrink-0 items-center justify-center rounded-sm text-muted-foreground outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 [&_svg]:size-4";

const useMergedRefs = <Element,>(
  first: Ref<Element> | undefined,
  second: Ref<Element> | undefined,
  third?: Ref<Element>,
  fourth?: Ref<Element>
) =>
  useCallback(
    (node: Element | null) => {
      const refs = [first, second, third, fourth];
      const cleanups = refs.map((ref) => {
        if (typeof ref === "function") {
          const cleanup = ref(node);
          return typeof cleanup === "function" ? cleanup : () => ref(null);
        }
        if (ref) {
          ref.current = node;
          return () => {
            ref.current = null;
          };
        }
        return null;
      });
      return () => {
        for (const cleanup of cleanups) {
          cleanup?.();
        }
      };
    },
    [first, second, third, fourth]
  );

export const AutocompleteInput = (props: AutocompleteInputProps) => {
  const a = useAutocomplete();
  const combined = mergeProps(a.config.inputProps, props);
  const ref = useMergedRefs(
    a.inputRef,
    a.config.ref,
    a.config.inputProps?.ref,
    props.ref
  );
  return (
    <Combobox.Input
      {...combined}
      ref={ref}
      data-slot="autocomplete-input"
      form={a.config.form}
      aria-label={combined["aria-label"] ?? a.config.label}
      aria-invalid={a.config.invalid || combined["aria-invalid"]}
      aria-required={a.config.required || undefined}
      placeholder={combined.placeholder ?? a.config.placeholder}
      className={cn(
        control,
        surface,
        "h-9 placeholder:text-muted-foreground disabled:pointer-events-none",
        a.config.size === "sm" && "h-8 min-h-8",
        combined.className
      )}
      onCompositionStart={(event) => {
        combined.onCompositionStart?.(event);
        a.composing.current = true;
      }}
      onCompositionEnd={(event) => {
        combined.onCompositionEnd?.(event);
        a.composing.current = false;
        a.endingComposition.current = true;
      }}
      onBlur={(event) => {
        combined.onBlur?.(event);
        if (!event.defaultPrevented && !event.baseUIHandlerPrevented) {
          a.restore();
        }
      }}
      onChange={(event) => {
        combined.onChange?.(event);
        if (event.defaultPrevented) {
          event.preventBaseUIHandler();
        }
      }}
      onKeyDown={(event) => {
        combined.onKeyDown?.(event);
        if (event.defaultPrevented || event.baseUIHandlerPrevented) {
          event.preventBaseUIHandler();
          return;
        }
        const cancel = () => {
          event.preventDefault();
          event.preventBaseUIHandler();
        };
        if (
          event.key === "Enter" &&
          (a.composing.current ||
            event.nativeEvent.isComposing ||
            event.nativeEvent.keyCode === 229 ||
            a.endingComposition.current)
        ) {
          cancel();
          a.endingComposition.current = false;
          return;
        }
        if (event.key !== "Enter") {
          a.endingComposition.current = false;
        }
        if (a.config.disabled || a.config.readOnly) {
          return;
        }
        if (event.key === "Escape") {
          cancel();
          a.restore();
          a.setOpen(false);
        } else if (a.multiple && event.key === "Backspace" && !a.text) {
          const chips = a.chipsRef.current?.querySelectorAll<HTMLElement>(
            '[data-slot="autocomplete-chip"]'
          );
          if (chips?.length) {
            cancel();
            chips.item(chips.length - 1)?.focus();
          }
        } else if (a.multiple && !a.selection && event.key === "Enter") {
          const activeId = event.currentTarget.getAttribute(
            "aria-activedescendant"
          );
          if (!activeId) {
            cancel();
            a.createTag();
          } else if (
            // IDs may contain selector metacharacters (including React's colons).
            // eslint-disable-next-line unicorn/prefer-query-selector
            document.getElementById(activeId)?.getAttribute("aria-disabled") ===
            "true"
          ) {
            cancel();
          }
        }
      }}
    />
  );
};

const PopupElement = ({
  nativeProps,
  ref,
  ...props
}: ComponentProps<"div"> & { nativeProps: ComponentProps<"div"> }) =>
  useRender({
    props: { ...nativeProps },
    ref: [nativeProps.ref ?? null, ref ?? null],
    render: <div {...props} />,
  });
const MotionPopup = motion.create(PopupElement);

export const AutocompleteContent = ({
  className,
  children,
  side = "bottom",
  sideOffset = 4,
  align = "start",
  alignOffset = 0,
  collisionBoundary,
  collisionPadding,
  ...props
}: AutocompleteContentProps & { children?: ReactNode }) => {
  const a = useAutocomplete();
  const reduced = useReducedMotion();
  const animated = a.config.animated !== false && !reduced;
  return (
    <Combobox.Portal style={{ left: 0, position: "absolute", top: 0 }}>
      <Combobox.Positioner
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
        collisionBoundary={collisionBoundary}
        collisionPadding={collisionPadding}
        className="isolate"
      >
        <Combobox.Popup
          {...props}
          data-slot="autocomplete-content"
          className={cn(
            "relative max-h-(--available-height) w-(--anchor-width) min-w-32 origin-(--transform-origin) overflow-hidden rounded-md border bg-popover text-popover-foreground shadow-md outline-none",
            className
          )}
          render={(nativeProps, state) => (
            <MotionPopup
              nativeProps={nativeProps}
              initial={{
                opacity: animated ? 0 : 1,
                scale: animated ? 0.96 : 1,
              }}
              animate={{
                opacity: state.open ? 1 : 0,
                scale: animated && !state.open ? 0.96 : 1,
              }}
              transition={{
                duration: animated ? (state.open ? 0.18 : 0.12) : 0,
                ease: [0.22, 1, 0.36, 1],
              }}
              onAnimationComplete={() => {
                if (!state.open) {
                  a.actionsRef.current?.unmount();
                }
              }}
            >
              {nativeProps.children}
            </MotionPopup>
          )}
        >
          {children}
        </Combobox.Popup>
      </Combobox.Positioner>
    </Combobox.Portal>
  );
};
export const AutocompleteList = ({
  className,
  ...props
}: Combobox.List.Props) => {
  const a = useAutocomplete();
  return (
  <Combobox.List
    {...props}
    data-slot="autocomplete-list"
    onScroll={(event) => {
      props.onScroll?.(event);
      const page = a.config.pagination;
      const list = event.currentTarget;
      if (!event.defaultPrevented && page?.automatic !== false && list.scrollTop > 0 && list.scrollHeight > list.clientHeight && list.scrollHeight - list.clientHeight - list.scrollTop <= 48) {
        void a.loadPage().catch(() => undefined);
      }
    }}
    className={cn(
      "max-h-[min(20rem,var(--available-height))] overflow-y-auto overscroll-contain p-1",
      className
    )}
  />
  );
};
export const AutocompleteItem = <Item,>({
  value,
  className,
  children,
  disabled,
  ...props
}: Omit<Combobox.Item.Props, "value" | "render" | "className" | "style"> & {
  value: Item;
  className?: string;
  style?: ComponentProps<"div">["style"];
}) => {
  const a = useAutocomplete();
  const option = a.resolveOption(value);
  if (!option || a.config.loading || a.config.error || a.config.hintMessage) {
    return null;
  }
  const { id } = option;
  const locked = Boolean(
    disabled ||
    option?.disabled ||
    a.config.disabled ||
    a.config.readOnly ||
    a.config.loading ||
    a.config.error
  );
  const Primitive = a.textSingle ? BaseAutocomplete.Item : Combobox.Item;
  return (
    <Primitive
      {...props}
      value={id}
      disabled={locked}
      data-slot="autocomplete-item"
      className={cn(
        "relative flex w-full min-w-0 cursor-pointer items-center gap-2 rounded-sm py-1.5 pr-8 pl-2 text-sm outline-none select-none data-highlighted:bg-accent data-highlighted:text-accent-foreground data-disabled:cursor-not-allowed data-disabled:opacity-50",
        className
      )}
    >
      <span className="min-w-0 flex-1 break-words">
        {children ?? option?.label ?? String(value)}
      </span>
      {!a.textSingle && (
        <Combobox.ItemIndicator className="absolute right-2 [&_svg]:size-4">
          <CheckIcon aria-hidden="true" />
        </Combobox.ItemIndicator>
      )}
    </Primitive>
  );
};
export const AutocompleteGroup = ({
  className,
  ...props
}: Combobox.Group.Props) => (
  <Combobox.Group
    {...props}
    data-slot="autocomplete-group"
    className={cn("scroll-my-1", className)}
  />
);
export const AutocompleteGroupLabel = ({
  className,
  ...props
}: Combobox.GroupLabel.Props) => (
  <Combobox.GroupLabel
    {...props}
    data-slot="autocomplete-group-label"
    className={cn("px-2 py-1.5 text-xs text-muted-foreground", className)}
  />
);
export const AutocompleteEmpty = ({
  children,
  className,
  ...props
}: ComponentProps<"div">) => {
  const a = useAutocomplete();
  if (a.options.length || a.config.loading || a.config.error || a.config.hintMessage) {
    return null;
  }
  return (
    <div
      {...props}
      role="status"
      data-slot="autocomplete-empty"
      className={cn("px-3 py-3 text-sm text-muted-foreground", className)}
    >
      {children ?? a.config.emptyMessage ?? "No results found."}
    </div>
  );
};
export const AutocompleteStatus = ({
  children,
  className,
  ...props
}: ComponentProps<"div">) => {
  const a = useAutocomplete();
  const message =
    a.config.error ||
    (a.config.loading
      ? (a.config.loadingMessage ?? "Loading suggestions…")
      : children);
  if (!message) {
    return null;
  }
  return (
    <div
      {...props}
      role="status"
      aria-live="polite"
      data-slot="autocomplete-status"
      className={cn("px-3 py-3 text-sm text-muted-foreground", className)}
    >
      {message}
    </div>
  );
};
export const AutocompleteClear = ({
  className,
  children,
  onClick,
  ...props
}: ComponentProps<"button">) => {
  const a = useAutocomplete();
  return (
    <button
      {...props}
      type="button"
      data-slot="autocomplete-clear"
      aria-label={props["aria-label"] ?? a.config.clearLabel ?? "Clear value"}
      disabled={props.disabled || a.config.disabled || a.config.readOnly}
      className={cn(action, className)}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) {
          a.clear();
        }
      }}
    >
      {children ?? <XIcon aria-hidden="true" />}
    </button>
  );
};
export const AutocompleteTrigger = ({
  className,
  children,
  ...props
}: Combobox.Trigger.Props) => {
  const a = useAutocomplete();
  return (
    <Combobox.Trigger
      {...props}
      data-slot="autocomplete-trigger"
      disabled={props.disabled || a.config.disabled || a.config.readOnly}
      aria-label={props["aria-label"] ?? "Show suggestions"}
      className={cn(action, className)}
    >
      {children ?? <ChevronDownIcon aria-hidden="true" />}
    </Combobox.Trigger>
  );
};
export const AutocompleteChips = ({
  className,
  ...props
}: Combobox.Chips.Props) => {
  const a = useAutocomplete();
  const ref = useMergedRefs(a.chipsRef, props.ref);
  if (!a.multiple) {
    throw new Error("AutocompleteChips requires multiple.");
  }
  return (
    <Combobox.Chips
      {...props}
      ref={ref}
      data-slot="autocomplete-chips"
      className={cn(
        "flex min-w-0 flex-1 flex-wrap items-center gap-1 py-1",
        className
      )}
    />
  );
};
const ChipLabelContext = createContext("");
export const AutocompleteChip = ({
  className,
  label,
  children,
  ...props
}: Combobox.Chip.Props & { label: string }) => (
  <ChipLabelContext.Provider value={label}>
    <Combobox.Chip
      {...props}
      data-slot="autocomplete-chip"
      aria-label={props["aria-label"] ?? label}
      className={cn(
        "inline-flex max-w-full items-center gap-1 rounded-sm bg-accent py-0.5 pr-0.5 pl-2 text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring",
        className
      )}
    >
      {children ?? <span className="min-w-0 truncate">{label}</span>}
    </Combobox.Chip>
  </ChipLabelContext.Provider>
);
export const AutocompleteChipRemove = ({
  className,
  children,
  ...props
}: Combobox.ChipRemove.Props) => {
  const a = useAutocomplete();
  const label = useContext(ChipLabelContext);
  return (
    <Combobox.ChipRemove
      {...props}
      data-slot="autocomplete-chip-remove"
      aria-label={
        props["aria-label"] ??
        a.config.removeLabel?.(label) ??
        `Remove ${label}`
      }
      disabled={props.disabled || a.config.disabled || a.config.readOnly}
      className={cn(action, "size-5 [&_svg]:size-3", className)}
    >
      {children ?? <XIcon aria-hidden="true" />}
    </Combobox.ChipRemove>
  );
};

const Assembly = <Item,>({ props }: { props: AutocompleteProps<Item> }) => {
  const a = useAutocomplete();
  const generatedId = useId();
  const id = props.inputProps?.id ?? generatedId;
  const [focused, setFocused] = useState(false);
  const floating = props.label && props.labelStyle === "floating";
  const raised = focused || a.text.length > 0 || a.selected.length > 0;
  const label = props.label ? (
    <label
      htmlFor={id}
      data-floating={raised}
      className={cn(
        "text-sm font-medium",
        floating &&
          "pointer-events-none absolute left-3 z-10 max-w-[calc(100%-1.5rem)] truncate bg-background px-1 font-normal text-muted-foreground transition-[top,transform] duration-150 motion-reduce:transition-none",
        floating &&
          (raised
            ? "top-0 -translate-y-1/2 text-xs"
            : "top-1/2 -translate-y-1/2")
      )}
    >
      {props.label}
    </label>
  ) : null;
  const editable = (
    <AutocompleteInput
      id={id}
      className={cn(
        "h-7 min-h-7 min-w-16 flex-1 rounded-none border-0 bg-transparent bg-none px-0 shadow-none focus-within:ring-0 dark:bg-transparent",
        floating && !raised && "placeholder:text-transparent"
      )}
      onFocus={() => setFocused(true)}
      onBlur={() => setFocused(false)}
    />
  );
  const groups = groupAutocompleteItems(
    a.options,
    props.groupBy
      ? (option) => props.groupBy?.(option.item as Item) ?? ""
      : undefined
  );
  return (
    <div
      data-slot="autocomplete-field"
      className={cn("relative grid min-w-0 gap-1.5", props.className)}
    >
      {!floating && label}
      <div className="relative min-w-0">
        <Combobox.InputGroup
          data-slot="autocomplete-control"
          data-disabled={props.disabled || undefined}
          data-invalid={props.invalid || undefined}
          className={cn(
            control,
            surface,
            "flex items-center gap-1",
            props.size === "sm" && "min-h-8"
          )}
        >
          {a.multiple ? (
            <AutocompleteChips>
              {a.selected.map((entry) => (
                <AutocompleteChip key={entry.id} label={entry.label}>
                  <span className="min-w-0 truncate">{entry.label}</span>
                  <AutocompleteChipRemove />
                </AutocompleteChip>
              ))}
              {editable}
            </AutocompleteChips>
          ) : (
            editable
          )}
          {props.clearable && <AutocompleteClear />}
          {(props.showTrigger ?? a.selection) && <AutocompleteTrigger />}
        </Combobox.InputGroup>
        {floating && label}
      </div>
      <AutocompleteContent {...props.contentProps}>
        <AutocompleteFeedback />
        <AutocompleteList>
          {!props.loading &&
            !props.error &&
            !props.hintMessage &&
            groups.map((group, index) => (
              <AutocompleteGroup key={group.label ?? index}>
                {group.label !== undefined && (
                  <AutocompleteGroupLabel>{group.label}</AutocompleteGroupLabel>
                )}
                {group.items.map((option) => (
                  <AutocompleteItem key={option.id} value={option.item as Item}>
                    {props.renderItem?.(option.item as Item) ?? option.label}
                  </AutocompleteItem>
                ))}
              </AutocompleteGroup>
            ))}
        </AutocompleteList>
        <AutocompletePagination />
      </AutocompleteContent>
    </div>
  );
};
export const Autocomplete = <Item,>(props: AutocompleteProps<Item>) => (
  <AutocompleteRoot<Item> key="root" {...props}>
    <Assembly props={props} />
  </AutocompleteRoot>
);
export { AutocompleteRoot };
export { AutocompleteFeedback, AutocompletePagination };
export type {
  AutocompleteProps,
  AutocompleteRootProps,
  AutocompleteValue,
  AutocompleteMode,
  AutocompleteInputProps,
  AutocompleteContentProps,
} from "./autocomplete-types";

"use client";

import { cn } from "cn";
import type { ComponentProps } from "react";
import { useAutocomplete } from "./autocomplete-root";
import { Loading } from "./loading";

export const AutocompleteFeedback = ({ children, className, ...props }: ComponentProps<"div">) => {
  const a = useAutocomplete();
  const c = a.config;
  const busy = c.loading || c.backgroundLoading;
  const message = c.hintMessage ?? c.error ?? (busy ? c.loadingMessage ?? "Loading suggestions…" : a.options.length === 0 ? c.emptyMessage ?? "No results found." : children);
  if (!message && !busy) {
    return null;
  }
  return <div {...props} role="status" aria-live="polite" data-slot="autocomplete-feedback" className={cn("flex min-w-0 items-center gap-2 px-3 py-2 text-sm text-muted-foreground", className)}>
    {busy && !c.hintMessage && <Loading size={16} {...c.loadingProps} role="presentation" aria-hidden="true" />}
    <span className="min-w-0 flex-1 break-words">{message}</span>
    {c.error && c.onRetry && <button type="button" disabled={c.disabled || c.readOnly || c.loading} className="shrink-0 rounded-sm px-2 py-1 text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring" onClick={() => { if (a.open && !c.disabled && !c.readOnly) { void c.onRetry?.(); } }}>{c.retryLabel ?? "Retry"}</button>}
  </div>;
};

"use client";

import { cn } from "cn";
import type { ComponentProps } from "react";
import { useAutocomplete } from "./autocomplete-root";
import { Loading } from "./loading";

export const AutocompletePagination = ({ className, ...props }: ComponentProps<"div">) => {
  const a = useAutocomplete();
  const c = a.config;
  const page = c.pagination;
  if (!page || (!page.hasNextPage && !page.error && !page.fetchingNextPage && !a.pageBusy)) {
    return null;
  }
  const busy = page.fetchingNextPage || a.pageBusy;
  return <div {...props} data-slot="autocomplete-pagination" className={cn("flex min-w-0 items-center gap-2 border-t px-3 py-2 text-sm", className)}>
    <span role="status" aria-live="polite" className="flex min-w-0 flex-1 items-center gap-2 break-words text-muted-foreground">
      {busy && <Loading size={16} {...c.loadingProps} role="presentation" aria-hidden="true" />}
      {busy ? page.loadingMessage ?? "Loading more…" : page.error}
    </span>
    <button type="button" disabled={busy || !a.open || page.disabled || c.disabled || c.readOnly || c.loading || Boolean(c.error || c.hintMessage)} className="shrink-0 rounded-sm px-2 py-1 outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50" onClick={() => { void a.loadPage(Boolean(page.error)).catch(() => undefined); }}>
      {page.error ? page.retryLabel ?? "Retry" : page.loadMoreLabel ?? "Load more"}
    </button>
  </div>;
};

"use client";

// The four public contracts intentionally branch inside one primitive adapter.
/* eslint-disable complexity, no-nested-ternary */

import { Autocomplete as BaseAutocomplete } from "@base-ui/react/autocomplete";
import { Combobox } from "@base-ui/react/combobox";
import { createContext, useContext, useEffect, useRef, useState } from "react";
import type { RefObject } from "react";

import type {
  AutocompleteCommonProps,
  AutocompleteRootProps,
} from "./autocomplete-types";
import { normalizeAutocompleteTag } from "./autocomplete-utils";

interface Option {
  id: string;
  label: string;
  item: unknown;
  disabled: boolean;
}
type Configuration = Omit<
  AutocompleteCommonProps<unknown>,
  | "getItemLabel"
  | "getItemValue"
  | "isItemDisabled"
  | "filter"
  | "groupBy"
  | "renderItem"
>;
interface Adapter {
  config: Configuration;
  selection: boolean;
  multiple: boolean;
  textSingle: boolean;
  text: string;
  selected: { id: string; label: string }[];
  options: Option[];
  resolveOption: (item: unknown) => Option | undefined;
  open: boolean;
  setOpen: (next: boolean) => void;
  restore: () => void;
  clear: () => void;
  createTag: () => void;
  inputRef: RefObject<HTMLInputElement | null>;
  chipsRef: RefObject<HTMLDivElement | null>;
  actionsRef: RefObject<Combobox.Root.Actions | null>;
  composing: RefObject<boolean>;
  endingComposition: RefObject<boolean>;
  pageBusy: boolean;
  loadPage: (retry?: boolean) => Promise<void>;
}
const AdapterContext = createContext<Adapter | null>(null);
export const useAutocomplete = () => {
  const adapter = useContext(AdapterContext);
  if (!adapter) {
    throw new Error("Autocomplete parts require AutocompleteRoot.");
  }
  return adapter;
};

export const AutocompleteRoot = <Item,>(props: AutocompleteRootProps<Item>) => {
  const selection = props.mode === "selection";
  const multiple = props.multiple === true;
  const textSingle = !selection && !multiple;
  const getLabel = (item: Item) => props.getItemLabel?.(item) ?? String(item);
  const getId = (item: Item) => props.getItemValue?.(item) ?? String(item);
  const initial = useRef(
    props.defaultValue ?? (multiple ? [] : selection ? null : "")
  );
  const [uncontrolled, setUncontrolled] = useState<
    Item | Item[] | string | string[] | null
  >(initial.current);
  const value = props.value === undefined ? uncontrolled : props.value;
  const selected = selection
    ? (multiple
        ? (value as Item[])
        : value === null
          ? []
          : [value as Item]
      ).map((item) => ({ id: getId(item), label: getLabel(item) }))
    : multiple
      ? (value as string[]).map((tag) => ({ id: tag, label: tag }))
      : [];
  const initialQuery = useRef(
    props.defaultInputValue ??
      (selection && !multiple ? (selected[0]?.label ?? "") : "")
  );
  const [draft, setDraft] = useState(initialQuery.current);
  const text = textSingle ? String(value ?? "") : (props.inputValue ?? draft);
  const [localOpen, setLocalOpen] = useState(props.defaultOpen ?? false);
  const open = props.open ?? localOpen;
  const inputRef = useRef<HTMLInputElement | null>(null);
  const chipsRef = useRef<HTMLDivElement | null>(null);
  const actionsRef = useRef<Combobox.Root.Actions | null>(null);
  const composing = useRef(false);
  const endingComposition = useRef(false);
  const blocked = Boolean(props.disabled || props.readOnly);
  const stale = Boolean(props.loading || props.error || props.hintMessage);
  const pageLock = useRef(false);
  const [pageBusy, setPageBusy] = useState(false);
  const loadPage = async (retry = false) => {
    const page = props.pagination;
    if (!page || !open || blocked || stale || page.disabled || page.fetchingNextPage || pageLock.current || (!retry && (page.error || !page.hasNextPage))) {
      return;
    }
    pageLock.current = true;
    setPageBusy(true);
    try {
      await (retry ? page.onRetry ?? page.onLoadMore : page.onLoadMore)();
    } finally {
      pageLock.current = false;
      setPageBusy(false);
    }
  };
  const { contains } = Combobox.useFilter({ sensitivity: "base" });
  const allOptions: Option[] = [];
  const seen = new Set<string>();
  for (const item of props.items) {
    const label = getLabel(item);
    const id = selection ? getId(item) : multiple ? label.trim() : label;
    if (!seen.has(id)) {
      seen.add(id);
      allOptions.push({
        disabled: Boolean(props.isItemDisabled?.(item)),
        id,
        item,
        label,
      });
    }
  }
  const filterOption = (option: Option) => {
    if (props.filter === null) {
      return true;
    }
    if (props.filter) {
      const customFilter = props.filter;
      return customFilter(option.item as Item, text);
    }
    return contains(option.label, text);
  };
  const options = allOptions.filter(filterOption);
  const labels = new Map(
    [...selected, ...allOptions].map((entry) => [entry.id, entry.label])
  );

  const requestValue = (next: typeof value) => {
    if (blocked) {
      return;
    }
    if (props.value === undefined) {
      setUncontrolled(next);
    }
    // Only the bridge erases value types. Public discriminants still determine
    // callback types; IDs are resolved to original source objects before emission.
    if (props.mode === "selection") {
      if (props.multiple) {
        props.onValueChange?.(next as Item[]);
      } else {
        props.onValueChange?.(next as Item | null);
      }
    } else if (props.multiple) {
      props.onValueChange?.(next as string[]);
    } else {
      props.onValueChange?.(next as string);
    }
  };
  const requestText = (next: string) => {
    if (blocked || next === text) {
      return;
    }
    if (textSingle) {
      requestValue(next);
    } else {
      if (props.inputValue === undefined) {
        setDraft(next);
      }
      props.onInputValueChange?.(next);
    }
  };
  const setOpen = (next: boolean) => {
    if (props.open === undefined) {
      setLocalOpen(next);
    }
    if (open !== next) {
      props.onOpenChange?.(next);
    }
  };
  const restore = () => {
    if (selection) {
      requestText(multiple ? "" : (selected[0]?.label ?? ""));
    }
  };
  const clear = () => {
    if (blocked) {
      return;
    }
    if (
      multiple
        ? selected.length > 0
        : selection
          ? value !== null
          : text.length > 0
    ) {
      requestValue(multiple ? [] : selection ? null : "");
    }
    if (!textSingle) {
      requestText("");
    }
    inputRef.current?.focus();
  };
  const createTag = () => {
    if (blocked || selection || !multiple) {
      return;
    }
    const tag = normalizeAutocompleteTag(text, value as string[]);
    if (tag !== null) {
      requestValue([...(value as string[]), tag]);
      requestText("");
      setOpen(true);
    }
  };
  const receiveIds = (
    next: string[] | string | null,
    details: Combobox.Root.ChangeEventDetails
  ) => {
    if (
      blocked ||
      details.reason === "input-clear" ||
      details.reason === "escape-key"
    ) {
      details.cancel();
      return;
    }
    const ids = [
      ...new Set(Array.isArray(next) ? next : next === null ? [] : [next]),
    ];
    const added = ids.filter(
      (id) => !selected.some((entry) => entry.id === id)
    );
    if (multiple && details.reason === "item-press" && added.length === 0) {
      details.cancel();
      return;
    }
    if (
      added.some(
        (id) => stale || allOptions.find((entry) => entry.id === id)?.disabled
      )
    ) {
      details.cancel();
      return;
    }
    if (multiple) {
      if (
        JSON.stringify(ids) !==
        JSON.stringify(selected.map((entry) => entry.id))
      ) {
        if (selection) {
          const old = value as Item[];
          const nextItems = ids.flatMap((id) => {
            // Preserve existing committed instances. New selections use current source.
            const item =
              old.find((entry) => getId(entry) === id) ??
              (allOptions.find((entry) => entry.id === id)?.item as
                | Item
                | undefined);
            return item === undefined ? [] : [item];
          });
          requestValue(nextItems);
        } else {
          const tags: string[] = [];
          for (const id of ids) {
            const tag = normalizeAutocompleteTag(id, tags);
            if (tag !== null) {
              tags.push(tag);
            }
          }
          requestValue(tags);
        }
      }
      if (added.length > 0) {
        requestText("");
        setOpen(true);
      }
    } else if (selection) {
      const option = allOptions.find((entry) => entry.id === next);
      if (option) {
        if (option.id !== selected[0]?.id) {
          requestValue(option.item as Item);
        }
        requestText(option.label);
        setOpen(false);
      }
    }
  };

  const committedLabel =
    selection && !multiple ? (selected[0]?.label ?? "") : "";
  const previousLabel = useRef(committedLabel);
  const resetting = useRef(false);
  useEffect(() => {
    if (
      previousLabel.current !== committedLabel &&
      !resetting.current &&
      props.inputValue === undefined
    ) {
      setDraft(committedLabel);
    }
    previousLabel.current = committedLabel;
    resetting.current = false;
  }, [committedLabel, props.inputValue, draft]);
  useEffect(() => {
    const missing =
      props.required && (textSingle ? !text : selected.length === 0);
    inputRef.current?.setCustomValidity(
      missing && !blocked ? "Please enter or select a value." : ""
    );
  });
  useEffect(() => {
    const form = inputRef.current?.form;
    if (!form) {
      return;
    }
    const reset = (event: Event) => {
      queueMicrotask(() => {
        if (!event.defaultPrevented) {
          if (props.value === undefined) {
            resetting.current = true;
            setUncontrolled(initial.current);
          }
          if (props.inputValue === undefined) {
            setDraft(initialQuery.current);
          }
          if (props.open === undefined) {
            setLocalOpen(false);
          }
          composing.current = false;
          endingComposition.current = false;
          actionsRef.current?.unmount();
        }
      });
    };
    form.addEventListener("reset", reset);
    return () => form.removeEventListener("reset", reset);
  }, [props.form, props.value, props.inputValue, props.open]);

  const bridge = {
    actionsRef,
    autoHighlight: props.autoHighlight ?? false,
    disabled: props.disabled,
    filter: null,
    filteredItems: stale ? [] : options.map((entry) => entry.id),
    form: props.form,
    items: allOptions.map((entry) => entry.id),
    onOpenChange(next: boolean, details: Combobox.Root.ChangeEventDetails) {
      if (
        !next &&
        ["escape-key", "focus-out", "outside-press"].includes(details.reason)
      ) {
        restore();
      }
      if (!(multiple && details.reason === "item-press")) {
        setOpen(next);
      }
    },
    open,
    readOnly: props.readOnly,
  };
  const formValues = textSingle
    ? [text]
    : multiple
      ? selected.map((entry) => entry.id)
      : [selected[0]?.id ?? ""];
  const children = (
    <>
      {props.children}
      {props.name &&
        formValues.map((entry, index) => (
          <input
            key={`${index}:${entry}`}
            type="hidden"
            name={props.name}
            form={props.form}
            value={entry}
            disabled={props.disabled}
          />
        ))}
    </>
  );
  const adapter: Adapter = {
    actionsRef,
    chipsRef,
    clear,
    composing,
    config: props,
    createTag,
    endingComposition,
    inputRef,
    multiple,
    pageBusy,
    loadPage,
    open,
    options,
    resolveOption: (item) => {
      const id = selection ? getId(item as Item) : getLabel(item as Item);
      return options.find(
        (option) => option.id === (multiple && !selection ? id.trim() : id)
      );
    },
    restore,
    selected,
    selection,
    setOpen,
    text,
    textSingle,
  };
  const queryChanged = (
    next: string,
    details: Combobox.Root.ChangeEventDetails
  ) => {
    if (details.reason === "input-change") {
      requestText(next);
    }
  };
  return (
    <AdapterContext.Provider value={adapter}>
      {textSingle ? (
        <BaseAutocomplete.Root
          {...bridge}
          value={text}
          itemToStringValue={(id) => labels.get(id) ?? id}
          onValueChange={(next, details) => {
            if (blocked || (stale && details.reason === "item-press")) {
              details.cancel();
            } else {
              requestText(next);
            }
          }}
        >
          {children}
        </BaseAutocomplete.Root>
      ) : multiple ? (
        <Combobox.Root<string, true>
          {...bridge}
          multiple
          value={selected.map((entry) => entry.id)}
          inputValue={text}
          itemToStringLabel={(id) => labels.get(id) ?? id}
          onInputValueChange={queryChanged}
          onValueChange={receiveIds}
        >
          {children}
        </Combobox.Root>
      ) : (
        <Combobox.Root<string>
          {...bridge}
          value={selected[0]?.id ?? null}
          inputValue={text}
          itemToStringLabel={(id) => labels.get(id) ?? id}
          onInputValueChange={queryChanged}
          onValueChange={receiveIds}
        >
          {children}
        </Combobox.Root>
      )}
    </AdapterContext.Provider>
  );
};

import type { Combobox } from "@base-ui/react/combobox";
import type { ComponentProps, ReactNode, Ref } from "react";
import type { LoadingProps } from "./loading";

export interface AutocompletePaginationProps {
  hasNextPage: boolean;
  fetchingNextPage: boolean;
  error?: ReactNode;
  disabled?: boolean;
  automatic?: boolean;
  onLoadMore: () => void | Promise<unknown>;
  onRetry?: () => void | Promise<unknown>;
  loadMoreLabel?: string;
  retryLabel?: string;
  loadingMessage?: ReactNode;
}

export type AutocompleteMode = "free-text" | "selection";
export type AutocompleteValue<
  Item,
  Mode extends AutocompleteMode,
  Multiple extends boolean,
> = Mode extends "selection"
  ? Multiple extends true
    ? Item[]
    : Item | null
  : Multiple extends true
    ? string[]
    : string;

export type AutocompleteInputProps = Omit<
  ComponentProps<"input">,
  | "children"
  | "value"
  | "defaultValue"
  | "name"
  | "form"
  | "disabled"
  | "readOnly"
  | "required"
  | "size"
  | "type"
>;
export type AutocompleteContentProps = Omit<
  Combobox.Popup.Props,
  "children" | "render"
> &
  Pick<
    Combobox.Positioner.Props,
    | "side"
    | "sideOffset"
    | "align"
    | "alignOffset"
    | "collisionBoundary"
    | "collisionPadding"
  >;

type Identity<Item> = [Item] extends [string]
  ? {
      getItemLabel?: (item: Item) => string;
      getItemValue?: (item: Item) => string;
    }
  : {
      getItemLabel: (item: Item) => string;
      getItemValue: (item: Item) => string;
    };

export type AutocompleteCommonProps<Item> = Identity<Item> & {
  items: readonly Item[];
  label?: string;
  labelStyle?: "static" | "floating";
  placeholder?: string;
  size?: "default" | "sm";
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  name?: string;
  form?: string;
  invalid?: boolean;
  loading?: boolean;
  backgroundLoading?: boolean;
  loadingProps?: LoadingProps;
  hintMessage?: ReactNode;
  onRetry?: () => void | Promise<unknown>;
  retryLabel?: string;
  pagination?: AutocompletePaginationProps;
  error?: ReactNode;
  emptyMessage?: ReactNode;
  loadingMessage?: ReactNode;
  clearLabel?: string;
  removeLabel?: (label: string) => string;
  clearable?: boolean;
  showTrigger?: boolean;
  autoHighlight?: boolean;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  filter?: ((item: Item, query: string) => boolean) | null;
  animated?: boolean;
  className?: string;
  inputProps?: AutocompleteInputProps;
  contentProps?: AutocompleteContentProps;
  ref?: Ref<HTMLInputElement>;
  renderItem?: (item: Item) => ReactNode;
  groupBy?: (item: Item) => string;
  isItemDisabled?: (item: Item) => boolean;
};

interface ValueProps<Value> {
  value?: Value;
  defaultValue?: Value;
  onValueChange?: (value: Value) => void;
}
interface QueryProps {
  inputValue?: string;
  defaultInputValue?: string;
  onInputValueChange?: (value: string) => void;
}
type FreeSingle = ValueProps<string> & {
  mode?: "free-text";
  multiple?: false;
  inputValue?: never;
  defaultInputValue?: never;
  onInputValueChange?: never;
};
type FreeMultiple = ValueProps<string[]> &
  QueryProps & { mode?: "free-text"; multiple: true };
type SelectionSingle<Item> = ValueProps<Item | null> &
  QueryProps & { mode: "selection"; multiple?: false };
type SelectionMultiple<Item> = ValueProps<Item[]> &
  QueryProps & { mode: "selection"; multiple: true };

export type AutocompleteProps<Item = string> = AutocompleteCommonProps<Item> &
  (
    | FreeSingle
    | FreeMultiple
    | SelectionSingle<NoInfer<Item>>
    | SelectionMultiple<NoInfer<Item>>
  ) & { children?: never };
export type AutocompleteRootProps<Item = string> =
  AutocompleteCommonProps<Item> &
    (
      | FreeSingle
      | FreeMultiple
      | SelectionSingle<NoInfer<Item>>
      | SelectionMultiple<NoInfer<Item>>
    ) & { children?: ReactNode };

export const normalizeAutocompleteTag = (
  draft: string,
  values: readonly string[]
): string | null => {
  const tag = draft.trim();
  return tag && !values.includes(tag) ? tag : null;
};

export const isAutocompleteItemEqual = <Item>(
  item: Item,
  value: Item,
  getItemValue?: (item: Item) => string
): boolean =>
  getItemValue
    ? getItemValue(item) === getItemValue(value)
    : Object.is(item, value);

export const groupAutocompleteItems = <Item>(
  items: readonly Item[],
  groupBy?: (item: Item) => string
): { label?: string; items: Item[] }[] => {
  if (!groupBy) {
    return items.length ? [{ items: [...items] }] : [];
  }
  const groups = new Map<string, { label: string; items: Item[] }>();
  for (const item of items) {
    const label = groupBy(item);
    const group = groups.get(label) ?? { items: [], label };
    group.items.push(item);
    groups.set(label, group);
  }
  return [...groups.values()];
};
